export enum TicketStatus {
  SUBMITTED = 'ثبت شده',
  PROCESSING = 'در حال بررسی',
  IN_PROGRESS = 'در دست اقدام',
  COMPLETED = 'تکمیل شده',
  CANCELLED = 'لغو شده'
}

export type Currency = 'IRR' | 'OMR' | 'USD';

export interface Price {
  amount: number;
  currency: Currency;
}

export interface AttachedFile {
  name: string;
  size: number;
  type: string;
  content: string; // Base64 or URL or Blob URL
  rawFile?: File; // Direct file reference for efficient upload
  // Upload Status Fields
  status?: 'pending' | 'uploading' | 'success' | 'error';
  progress?: number;
  errorMsg?: string;
}

export interface SubService {
  id: string;
  title: string;
  titleEn?: string;
  price?: Price;
}

export interface ServiceOption {
  id: string;
  title: string;
  titleEn?: string; // English Title
  description: string;
  descriptionEn?: string; // English Description
  icon: string;
  price?: Price; // Updated to Price Object
  isActive: boolean;
  subServices?: SubService[]; // Nested Services
  defaultCommission?: number; // Base commission percentage for this service
}

export interface PersonnelPermissions {
  canAssign: boolean; 
  canViewCustomers: boolean; 
  canViewTariffs: boolean; 
  canViewAllTickets: boolean;
  canIssueInvoices: boolean; // New permission for Invoicing
}

export interface PersonnelDocument {
  id: string;
  title: string;
  file: AttachedFile;
}

export interface Personnel {
  id: string;
  fullName: string;
  roles: string[]; 
  jobDescription?: string; 
  reportsTo?: string; // ID of the supervisor/manager
  email: string;
  username: string;
  password?: string;
  avatar?: string; 
  documents?: PersonnelDocument[]; 
  status: 'active' | 'inactive';
  permissions?: PersonnelPermissions;
  customCommissions?: Record<string, number>; // key: serviceId, value: percentage override
}

export interface Customer {
  id: string;
  fullName: string;
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string;
  email?: string;
  businessType?: string;
  firstContact: string;
  totalTickets: number;
  source?: string; 
  loyaltyCode?: string; // Unique code for discounts
}

export interface TimelineEntry {
  type: 'status_change' | 'comment' | 'assignment' | 'creation' | 'update' | 'project_update' | 'invoice_created';
  title: string;
  description?: string; 
  actorName: string; 
  timestamp: string;
  visibility?: 'public' | 'internal'; // Controls who sees this entry
}

export interface Payment {
  id: string;
  amount: number;
  currency: Currency;
  date: string;
  type: 'deposit' | 'settlement' | 'installment';
  note?: string;
}

export interface InvoiceItem {
  description: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

export interface Invoice {
  id: string;
  number: string;
  date: string;
  dueDate?: string;
  customerName: string;
  companyName?: string;
  items: InvoiceItem[];
  currency: Currency;
  subTotal: number;
  taxRate: number;
  taxAmount: number;
  discount: number;
  total: number;
  note?: string;
  issuedBy: string;
}

export interface ProjectMilestone {
  id: string;
  title: string;
  isCompleted: boolean;
  dueDate?: string;
}

export interface ProjectRisk {
  id: string;
  title: string;
  impact: 'Low' | 'Medium' | 'High';
}

export interface ProjectTeamMember {
  userId: string;
  role: string; // e.g. "Head of Design"
  responsibility: string; // Specific task description
  joinedAt: string;
}

export interface ProjectDetails {
  isActive: boolean;
  tariff?: Price; // Cost/Price Object
  startDate: string;
  endDate: string;
  teamMemberIds: string[]; 
  teamMembers?: ProjectTeamMember[]; // Detailed team structure
  projectFiles: AttachedFile[];
  payments: Payment[]; // List of payments
  invoices?: Invoice[]; // List of issued invoices
  milestones?: ProjectMilestone[];
  risks?: ProjectRisk[];
  progress: number; 
  statusNote?: string;
}

export interface Ticket {
  id: string;
  customerName: string; 
  companyName?: string; 
  location: string; 
  phoneNumber: string;
  whatsappNumber: string; 
  businessType?: string; 
  serviceId: string;
  selectedSubServices?: string[]; // Array of SubService IDs or Names
  description: string;
  files?: AttachedFile[];
  status: TicketStatus;
  createdAt: string;
  aiAnalysis?: string;
  priority?: 'Low' | 'Medium' | 'High';
  assignedTo?: string;
  timeline: TimelineEntry[]; 
  customData?: Record<string, string>; 
  projectData?: ProjectDetails;
  discountApplied?: boolean; // If loyalty discount was used
}

export interface InternalMessage {
  id: string;
  senderId: string;
  senderName: string;
  senderAvatar?: string;
  recipientIds: string[];
  recipientNames: string[];
  subject: string;
  body: string;
  files?: AttachedFile[];
  createdAt: string;
  readBy: string[]; // IDs of recipients who read the message
}

export interface TaskComment {
  id: string;
  authorId: string;
  authorName: string;
  text: string;
  timestamp: string;
}

export interface TaskChecklistItem {
  id: string;
  text: string;
  isCompleted: boolean;
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  creatorId: string;
  creatorName: string;
  assigneeIds: string[]; // List of personnel IDs responsible for this task
  isCompleted: boolean;
  checklist?: TaskChecklistItem[]; // Sub-tasks list
  dueDate?: string;
  priority: 'Low' | 'Medium' | 'High';
  createdAt: string;
  comments: TaskComment[];
}

export interface Meeting {
  id: string;
  title: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:mm
  endTime: string; // HH:mm
  location: string;
  organizerId: string;
  organizerName: string;
  attendeeIds: string[];
  description?: string;
}

export interface KPI {
  id: string;
  title: string;
  titleEn?: string;
  targetValue: number;
  currentValue: number;
  unit: 'percent' | 'count' | 'currency';
  period: 'monthly' | 'quarterly' | 'yearly';
  assignedRole?: string; // Role-based KPI
  assignedUserId?: string; // Specific User KPI
  description?: string;
}

export interface CustomForm {
  id: string;
  title: string;
  category: string; // e.g., 'ISO Standards', 'HR', 'Logistics'
  description?: string;
  fields: FormField[];
  allowedRoles: string[]; // Empty array means available to all
  createdAt: string;
  createdBy: string;
}

export interface SalesRecord {
  id: string;
  salespersonId: string;
  salespersonName: string;
  serviceId: string;
  serviceTitle: string;
  customerName: string;
  saleAmount: number;
  currency: Currency;
  commissionRate: number; // Percentage
  commissionAmount: number; // Calculated value
  depositAccount: string;
  depositDate: string;
  notes?: string;
  createdAt: string;
  updatedAt?: string;
  updatedBy?: string;
}

export interface SystemLog {
  id: string;
  actionType: 'CREATE' | 'UPDATE' | 'DELETE' | 'LOGIN' | 'OTHER';
  entity: 'Ticket' | 'Customer' | 'Personnel' | 'Project' | 'Task' | 'Meeting' | 'Message' | 'System' | 'KPI' | 'CustomForm' | 'Sale';
  entityId?: string;
  details: string;
  actorName: string;
  actorId?: string;
  timestamp: string;
  backupData?: any; // Stores the deleted data for restoration
  collectionName?: string; // Target collection for restoration
}

export interface FeaturedBusiness {
  id: string;
  name: string;
  description: string;
  imageUrl: string;
  websiteUrl?: string;
  contactNumber?: string;
  category: string;
  isGold: boolean; // Premium status for higher visibility
}

export type ViewState = 'landing' | 'new-ticket' | 'tracking' | 'admin';

export type FormFieldType = 'text' | 'textarea' | 'email' | 'tel' | 'select' | 'header' | 'date' | 'checkbox';

export interface FormField {
  id: string;
  key: string; 
  label: string;
  labelEn?: string;
  type: FormFieldType;
  required: boolean;
  placeholder?: string;
  placeholderEn?: string;
  options?: string[]; 
  isSystem?: boolean; 
  order: number;
}

export interface InvoiceTemplate {
  companyName: string;
  logoUrl?: string;
  address: string;
  phone: string;
  website?: string;
  footerText: string;
  termsConditions: string;
  defaultTaxRate: number; // Percentage
  colorTheme: string; // Hex Code
}

export interface AppConfig {
  appTitle: string;
  appTitleEn: string;
  appSubtitle: string;
  appSubtitleEn: string;

  // Landing Page Content
  landingHeroTitle?: string;
  landingHeroSubtitle?: string;
  footerText?: string;

  // Daily Content
  dailyTips?: string[];
  showDailyTips?: boolean;

  // Featured Businesses (Ads)
  featuredBusinesses?: FeaturedBusiness[];

  formFields: FormField[];
  personnelRoles?: string[]; 
  invoiceTemplate?: InvoiceTemplate;
}

