export const sanitizeData = (data: any): any => {
  if (data === undefined || data === null) return null;
  if (typeof data !== 'object') return data;
  if (data instanceof Date) return data.toISOString();

  const seen = new WeakSet();

  const deepCopy = (obj: any): any => {
    if (obj === undefined || obj === null) return null;
    if (typeof obj !== 'object') return obj;
    if (obj instanceof Date) return obj.toISOString();

    // Cycle detection
    if (seen.has(obj)) return null;
    seen.add(obj);

    if (Array.isArray(obj)) {
      return obj.map(deepCopy).filter(item => item !== undefined);
    }

    // Safety Check: Filter out non-plain objects
    // This catches Firebase internals (like Q$1), DOM nodes, and React SyntheticEvents
    const proto = Object.getPrototypeOf(obj);
    if (proto && proto.constructor && proto.constructor.name !== 'Object') {
        // Exception: Allow objects created with Object.create(null) which have no prototype
        if (proto !== null) return null;
    }

    // Duck typing for React Events or DOM Nodes just in case constructor check fails
    if (obj._reactName || (obj.nativeEvent && obj.target) || (obj.nodeType && obj.nodeName)) {
        return null;
    }

    const res: any = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        // Skip specific problematic keys often found in circular structures
        if (key.startsWith('_') || key === 'src' || key === 'target' || key === 'view' || key === 'nativeEvent' || key === 'rawFile') continue;

        const val = deepCopy(obj[key]);
        if (val !== undefined) {
          res[key] = val;
        }
      }
    }
    return res;
  };

  return deepCopy(data);
};

export const compressImage = (file: File, maxWidth = 800, quality = 0.5): Promise<string> => {
    return new Promise((resolve, reject) => {
        if (!file.type.startsWith('image/')) {
            return resolve("");
        }

        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;

                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(img, 0, 0, width, height);
                    const dataUrl = canvas.toDataURL('image/jpeg', quality);
                    resolve(dataUrl);
                } else {
                    resolve(event.target?.result as string);
                }
            };
            img.onerror = () => resolve(""); 
        };
        reader.onerror = () => resolve("");
    });
};

const fileToDataURL = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
};

// --- ROBUST UPLOAD STRATEGY ---
export const uploadFileWithProgress = async (
    file: File, 
    onProgress: (progress: number) => void,
    onSuccess: (url: string) => void,
    onError: (error: Error) => void
) => {
    // STRATEGY 1: IF IMAGE, BYPASS STORAGE COMPLETELY (Guarantee Success)
    if (file.type.startsWith('image/')) {
        try {
            onProgress(20);
            const base64 = await compressImage(file, 800, 0.5);
            onProgress(60);

            if (base64) {
                setTimeout(() => {
                    onProgress(100);
                    onSuccess(base64);
                }, 300); 
                return; 
            }
        } catch (e) {
            console.error("Compression failed", e);
        }
    }

    // STRATEGY 2: IF PDF AND SMALL (< 2MB), USE BASE64 (Increased limit for better UX)
    if (file.type === 'application/pdf' && file.size < 2 * 1024 * 1024) {
        try {
            onProgress(30);
            const base64 = await fileToDataURL(file);
            onProgress(100);
            onSuccess(base64);
            return;
        } catch (e) {}
    }

    // STRATEGY 3: REGULAR STORAGE UPLOAD (Only for large PDFs or videos)
    const dateFolder = new Date().toISOString().split('T')[0];
    const safeName = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');
    const storageRef = ref(storage, `uploads/${dateFolder}/${Date.now()}_${safeName}`);

    const uploadTask = uploadBytesResumable(storageRef, file);

    // Watchdog Timer to prevent hanging at 0%
    const watchdog = setTimeout(() => {
        if (uploadTask.snapshot.bytesTransferred === 0) {
            uploadTask.cancel();
            onError(new Error("آپلود کند است یا دسترسی مسدود شده است."));
        }
    }, 15000);

    uploadTask.on('state_changed',
        (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            onProgress(progress);
            if (progress > 0) clearTimeout(watchdog);
        },
        (error) => {
            clearTimeout(watchdog);
            console.error("Storage Error:", error);
            onError(new Error("آپلود ناموفق. لطفاً اتصال اینترنت را بررسی کنید."));
        },
        () => {
            clearTimeout(watchdog);
            getDownloadURL(uploadTask.snapshot.ref).then((downloadURL) => {
                onSuccess(downloadURL);
            });
        }
    );
};

// --- System Maintenance Tools ---

export const backupSystemData = async () => {
    try {
        const collections = ['tickets', 'customers', 'settings', 'messages', 'tasks', 'meetings', 'kpis', 'custom_forms', 'sales_records'];
        const data: any = {};

        for (const col of collections) {
            const snap = await getDocs(collection(db, col));
            data[col] = snap.docs.map(d => d.data());
        }

        // Use sanitizeData before JSON.stringify to prevent crashes during backup
        const safeData = sanitizeData(data);
        const blob = new Blob([JSON.stringify(safeData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CRM_Backup_${new Date().toISOString().split('T')[0]}.json`;
        a.click();
        URL.revokeObjectURL(url);
        return true;
    } catch (e) {
        console.error("Backup failed", e);
        return false;
    }
};

export const clearSystemData = async () => {
    try {
        const ticketsSnap = await getDocs(collection(db, 'tickets'));
        const batch = writeBatch(db);
        ticketsSnap.docs.forEach(d => batch.delete(d.ref));
        await batch.commit();
        return true;
    } catch (e) {
        console.error("Clear failed", e);
        return false;
    }
};

// --- Logging System ---

export const logSystemAction = async (
    actionType: SystemLog['actionType'],
    entity: SystemLog['entity'],
    details: string,
    actorName: string,
    entityId?: string,
    backupData?: any,
    collectionName?: string
) => {
    try {
        const logEntry: SystemLog = {
            id: `log-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
            actionType,
            entity,
            details,
            actorName,
            entityId,
            timestamp: new Date().toISOString(),
            backupData,
            collectionName
        };
        // Ensure sanitizeData is called to prevent JSON cycles
        await setDoc(doc(db, "system_logs", logEntry.id), sanitizeData(logEntry));
    } catch (e) {
        console.error("Failed to log action", e);
    }
};

export const subscribeToSystemLogs = (callback: (logs: SystemLog[]) => void) => {
    const q = query(collection(db, "system_logs"), orderBy("timestamp", "desc"), limit(100));
    return onSnapshot(q, (snapshot) => {
        const logs = snapshot.docs.map(d => d.data() as SystemLog);
        callback(logs);
    }, (e) => {});
};

export const fetchAnalyticsData = async () => {
    try {
        // Fetch last 1000 logs for analysis
        const q = query(collection(db, "system_logs"), orderBy("timestamp", "desc"), limit(1000));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(d => d.data() as SystemLog);
    } catch (e) {
        console.error("Analytics fetch failed", e);
        return [];
    }
};

export const restoreEntityFromLog = async (log: SystemLog): Promise<boolean> => {
    if (!log.backupData || !log.collectionName || !log.entityId) return false;
    try {
        await setDoc(doc(db, log.collectionName, log.entityId), log.backupData);
        await logSystemAction('UPDATE', log.entity, `بازیابی اطلاعات حذف شده`, log.actorName, log.entityId);
        return true;
    } catch (e) {
        console.error("Restoration failed", e);
        return false;
    }
};

// --- Helper to clean file objects for Firestore ---
const cleanFilesForDB = (files: AttachedFile[] | undefined) => {
    if (!files) return [];
    return files.map(f => ({
        name: f.name,
        size: f.size,
        type: f.type,
        content: f.content 
    })).filter(f => f.content && !f.content.startsWith('blob:')); 
};

