  };

  const getSubServiceTitle = (serviceId: string, subId: string) => {
      const s = services.find(s => s.id === serviceId);
      const sub = s?.subServices?.find(sub => sub.id === subId);
      if (!sub) return subId;
      return lang === 'en' && sub.titleEn ? sub.titleEn : sub.title;
