  const calculateFinancials = () => {
      const totalContract = projectForm.tariff?.amount || 0;
      const totalInvoiced = (projectForm.invoices || []).reduce((acc, inv) => acc + inv.total, 0);
      const totalPaid = projectForm.payments.reduce((acc, p) => acc + p.amount, 0);
      const balance = totalContract - totalPaid;
      return { totalContract, totalInvoiced, totalPaid, balance };
  };

  const { totalContract, totalInvoiced, totalPaid, balance } = calculateFinancials();

  const renderFinancialReport = () => {
      const allProjects = tickets.filter(t => t.projectData?.isActive);

      const totalRevenue = allProjects.reduce((sum, t) => sum + (t.projectData?.tariff?.amount || 0), 0);
      const totalCollected = allProjects.reduce((sum, t) => sum + (t.projectData?.payments?.reduce((p, c) => p + c.amount, 0) || 0), 0);
      const pending = totalRevenue - totalCollected;

      // Group revenue by service
      const serviceRevenue: Record<string, number> = {};
      allProjects.forEach(t => {
          const sName = getServiceTitle(t.serviceId);
          serviceRevenue[sName] = (serviceRevenue[sName] || 0) + (t.projectData?.tariff?.amount || 0);
      });

      return (
