                                            <div className={`flex-grow ${m.isCompleted ? 'line-through text-gray-400' : 'text-gray-800'}`}>
                                                <div className="font-bold text-sm">{m.title}</div>
                                                <div className="text-xs text-gray-500">{m.dueDate}</div>
                                            </div>
                                            <button onClick={() => setProjectForm(prev => ({...prev, milestones: prev.milestones?.filter(item => item.id !== m.id)}))} className="text-red-300 hover:text-red-500"><IconTrash className="w-4 h-4" /></button>
                                        </div>
                                    ))}
                                </div>
                                <div className="flex gap-2">
                                    <input className="flex-grow border rounded p-2 text-sm" placeholder="Title" value={newMilestoneTitle} onChange={e => setNewMilestoneTitle(e.target.value)} />
                                    <input className="border rounded p-2 text-sm" type="date" value={newMilestoneDate} onChange={e => setNewMilestoneDate(e.target.value)} />
                                    <button onClick={handleAddMilestone} className="bg-indigo-50 text-indigo-600 border border-indigo-200 px-4 rounded text-sm font-bold hover:bg-indigo-100">+</button>
                                </div>
                            </div>

                            {/* Financials: Invoices & Payments */}
                            <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                                <div className="flex justify-between items-center border-b border-gray-100 pb-2 mb-4">
                                    <h4 className="font-bold text-gray-800">{t.financialDash}</h4>
                                    {canManageInvoices && (
                                        <button onClick={() => { setEditingInvoice(undefined); setShowInvoiceModal(true); }} className="text-xs bg-indigo-600 text-white px-3 py-1.5 rounded-lg font-bold hover:bg-indigo-700 flex items-center gap-1">
                                            <IconInvoice className="w-3 h-3" /> {t.issueInvoice}
                                        </button>
                                    )}
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    {/* Invoices List */}
                                    <div>
                                        <h5 className="text-xs font-bold text-gray-500 mb-2">Invoices</h5>
                                        {projectForm.invoices && projectForm.invoices.length > 0 ? (
                                            <div className="space-y-2">
                                                {projectForm.invoices.map(inv => (
                                                    <div key={inv.id} className="flex justify-between items-center bg-gray-50 p-2 rounded text-sm border border-gray-200">
                                                        <div><div className="font-bold">{inv.number}</div><div className="text-xs text-gray-500">{inv.date}</div></div>
                                                        <div className="font-bold">{inv.total.toLocaleString()}</div>
                                                        <button onClick={() => { setEditingInvoice(inv); setShowInvoiceModal(true); }} className="text-blue-500 text-xs hover:underline">{t.edit}</button>
                                                    </div>
                                                ))}
                                            </div>
                                        ) : <div className="text-sm text-gray-400 italic">No invoices issued</div>}
                                    </div>
                                    {/* Payments List */}
                                    <div>
                                        <h5 className="text-xs font-bold text-gray-500 mb-2">Payments Received</h5>
                                        <div className="space-y-2 mb-2">
                                            {projectForm.payments.map((p, i) => (
                                                <div key={i} className="flex justify-between items-center bg-green-50 p-2 rounded text-sm border border-green-100">
                                                    <div><div className="font-bold">{p.type}</div><div className="text-xs text-gray-500">{p.date}</div></div>
                                                    <div className="font-bold text-green-700">{p.amount.toLocaleString()}</div>
                                                    <button onClick={() => setProjectForm(prev => ({...prev, payments: prev.payments.filter((_, idx) => idx !== i)}))} className="text-red-300 hover:text-red-500"><IconTrash className="w-3 h-3" /></button>
                                                </div>
                                            ))}
                                        </div>
                                        <div className="flex gap-2">
                                            <input type="number" className="w-24 border rounded p-1 text-sm" placeholder="Amount" value={newPayment.amount || ''} onChange={e => setNewPayment({...newPayment, amount: parseInt(e.target.value) || 0})} />
                                            <select className="border rounded p-1 text-sm bg-white" value={newPayment.type} onChange={e => setNewPayment({...newPayment, type: e.target.value as any})}><option value="deposit">Deposit</option><option value="settlement">Settlement</option><option value="installment">Installment</option></select>
                                            <button onClick={() => { if(!newPayment.amount) return; setProjectForm(prev => ({...prev, payments: [...prev.payments, { id: `pay-${Date.now()}`, amount: newPayment.amount!, currency: projectForm.tariff?.currency || 'IRR', date: new Date().toISOString().split('T')[0], type: newPayment.type as any }] })); setNewPayment({...newPayment, amount: 0}); }} className="bg-green-600 text-white px-3 rounded text-sm font-bold hover:bg-green-700">{t.recordPayment}</button>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Project Files */}
                            <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                                <h4 className="font-bold text-gray-800 border-b border-gray-100 pb-2 mb-4">{t.projectDocs}</h4>
                                <div className="flex flex-wrap gap-3 mb-4">
                                    {(projectForm.projectFiles || []).map((f, i) => (
                                        <div key={i} className="relative group bg-gray-50 border border-gray-200 p-2 rounded-lg flex items-center gap-2">
                                            <IconFile className="w-4 h-4 text-gray-500" />
                                            <a href={f.content} target="_blank" className="text-sm text-blue-600 hover:underline truncate max-w-[150px]">{f.name}</a>
                                            <button onClick={() => handleRemoveProjectFile(i)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity"><IconTrash className="w-3 h-3" /></button>
                                        </div>
                                    ))}
                                </div>
                                <div onClick={() => projectFileInputRef.current?.click()} className="border-2 border-dashed border-gray-300 rounded-lg p-4 text-center cursor-pointer hover:bg-gray-50 hover:border-indigo-300 transition-colors">
                                    <IconUpload className="w-6 h-6 text-gray-400 mx-auto mb-1" />
                                    <span className="text-xs text-gray-500">{t.uploadHint}</span>
                                    <input type="file" ref={projectFileInputRef} className="hidden" multiple onChange={handleProjectFileUpload} />
                                </div>
                            </div>

                            <button onClick={handleSaveProject} className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-all active:scale-95">{t.saveProject}</button>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="p-4 border-t border-gray-100 bg-white shrink-0 flex justify-end">
                    <button onClick={() => setSelectedTicketId(null)} className="px-6 py-2 bg-gray-100 text-gray-700 hover:bg-gray-200 rounded-xl font-bold transition-colors flex items-center gap-2">
                        {lang === 'fa' ? 'بستن' : 'Close'}
                    </button>
                </div>
            </div>
        </div>
    );
  };

  return (
    <div className="flex flex-col md:flex-row gap-6 min-h-[calc(100vh-100px)]">
      {showInvoiceModal && selectedTicket && (
          <InvoiceModal 
             customer={{ id: selectedTicket.customerName, fullName: selectedTicket.customerName, companyName: selectedTicket.companyName, location: selectedTicket.location, phoneNumber: selectedTicket.phoneNumber, whatsappNumber: selectedTicket.whatsappNumber, firstContact: '', totalTickets: 0 }}
             template={config.invoiceTemplate || { companyName: config.appTitle, address: '', phone: '', footerText: '', termsConditions: '', defaultTaxRate: 0, colorTheme: '#4f46e5' }}
             initialData={editingInvoice}
             onSave={handleSaveInvoice}
             onClose={() => setShowInvoiceModal(false)}
          />
      )}

      {showNewProjectModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
              <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-fade-in overflow-hidden">
                  <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-purple-50">
                      <h3 className="font-bold text-lg text-purple-900 flex items-center gap-2"><IconProject className="w-5 h-5" />{t.newProject}</h3>
                      <button onClick={handleProjectModalClose} className="text-gray-400 hover:text-gray-600">✕</button>
                  </div>
                  {createdProjectId ? (
                      <div className="p-8 text-center"><div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4"><IconCheck className="w-8 h-8 text-green-600" /></div><h3 className="text-xl font-bold text-gray-800 mb-2">{t.successProject}</h3><p className="text-gray-500 text-sm mb-6">Tracking Code:</p><div className="bg-gray-50 border-2 border-dashed border-purple-200 rounded-xl p-4 flex items-center justify-between gap-3 mb-6"><span className="font-mono font-black text-2xl text-purple-700 tracking-wider">{createdProjectId}</span><button onClick={() => { navigator.clipboard.writeText(createdProjectId); alert(t.copyCode); }} className="bg-white border border-gray-200 text-gray-600 hover:text-purple-600 hover:border-purple-300 p-2 rounded-lg transition-colors"><IconCopy className="w-5 h-5" /></button></div><button onClick={handleProjectModalClose} className="w-full py-3 bg-purple-600 text-white rounded-xl font-bold hover:bg-purple-700 transition-colors">{t.understand}</button></div>
                  ) : (
                      <form onSubmit={handleCreateProject} className="p-6 space-y-4">
                          <div><label className="block text-sm font-bold text-gray-700 mb-1">{t.projectTitle}</label><input required className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" value={newProjectData.title} onChange={e => setNewProjectData({...newProjectData, title: e.target.value})} /></div>
                          <div><label className="block text-sm font-bold text-gray-700 mb-1">{t.relatedService}</label><select className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500 bg-white" required value={newProjectData.serviceId} onChange={e => setNewProjectData({...newProjectData, serviceId: e.target.value})}><option value="">...</option>{services.map(s => <option key={s.id} value={s.id}>{lang === 'en' && s.titleEn ? s.titleEn : s.title}</option>)}</select></div>
                          <div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.customer}</label><input required className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" value={newProjectData.customerName} onChange={e => setNewProjectData({...newProjectData, customerName: e.target.value})} /></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.phone}</label><input required className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500 dir-ltr text-right" value={newProjectData.phoneNumber} onChange={e => setNewProjectData({...newProjectData, phoneNumber: e.target.value})} /></div></div>
                          <div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.startDate}</label><input type="date" className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" value={newProjectData.startDate} onChange={e => setNewProjectData({...newProjectData, startDate: e.target.value})} /></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.endDate}</label><input type="date" className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" value={newProjectData.endDate} onChange={e => setNewProjectData({...newProjectData, endDate: e.target.value})} /></div></div>
                          <div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.contractAmount}</label><div className="flex gap-2"><input className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500" placeholder="0" value={newProjectData.tariffAmount} onChange={e => setNewProjectData({...newProjectData, tariffAmount: formatNumberInput(e.target.value)})} /><select className="px-2 py-2 rounded-lg border border-gray-300 bg-white" value={newProjectData.tariffCurrency} onChange={e => setNewProjectData({...newProjectData, tariffCurrency: e.target.value as Currency})}><option value="IRR">IRR</option><option value="USD">USD</option><option value="OMR">OMR</option></select></div></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.priority}</label><select className="w-full px-3 py-2 rounded-lg border border-gray-300 outline-none focus:ring-2 focus:ring-purple-500 bg-white" value={newProjectData.priority} onChange={e => setNewProjectData({...newProjectData, priority: e.target.value as any})}><option value="Low">Low</option><option value="Medium">Medium</option><option value="High">High</option></select></div></div>
                          <div className="flex gap-3 pt-4"><button type="button" onClick={handleProjectModalClose} className="flex-1 py-2.5 bg-gray-100 text-gray-700 rounded-xl font-bold hover:bg-gray-200">{t.cancel}</button><button type="submit" className="flex-1 py-2.5 bg-purple-600 text-white rounded-xl font-bold hover:bg-purple-700 shadow-lg shadow-purple-200">{t.create}</button></div>
                      </form>
                  )}
              </div>
          </div>
      )}

      <div className="w-full md:w-72 shrink-0 space-y-6">
         <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col items-center text-center sticky top-24">
            <div className="relative w-24 h-24 mb-4"><div className="w-full h-full rounded-full overflow-hidden border-2 border-indigo-100 shadow-md">{currentUser.avatar ? (<img src={currentUser.avatar} alt={currentUser.fullName} className="w-full h-full object-cover" />) : (<div className="w-full h-full bg-gray-100 flex items-center justify-center text-gray-400 text-2xl font-bold">{currentUser.fullName.charAt(0)}</div>)}</div><div className="absolute bottom-0 right-0 bg-green-500 w-4 h-4 rounded-full border-2 border-white"></div></div>
            <h3 className="font-bold text-gray-900 text-lg">{currentUser.fullName}</h3>
            <div className="flex flex-wrap justify-center gap-1 mt-1 mb-2">{(currentUser.roles || []).map((r, i) => (<span key={i} className="text-xs text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100">{r}</span>))}</div>
            {directManager && (<div className="text-xs text-gray-500 mb-4 bg-gray-50 px-2 py-1 rounded inline-flex items-center gap-1"><IconLayout className="w-3 h-3" /> {t.manager}: {directManager.fullName}</div>)}
            <div className="w-full space-y-2">
                <button onClick={() => setActiveTab('overview')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'overview' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconActivity className="w-5 h-5" /><span className="font-medium">{t.overview}</span></button>
                <button onClick={() => setActiveTab('tasks')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all relative ${activeTab === 'tasks' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconList className="w-5 h-5" /><span className="font-medium">{t.tasks}</span>{pendingTasksCount > 0 && <span className="absolute rtl:left-4 ltr:right-4 bg-amber-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{pendingTasksCount}</span>}</button>
                <button onClick={() => setActiveTab('meetings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'meetings' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconCalendarClock className="w-5 h-5" /><span className="font-medium">{t.meetings}</span></button>
                <button onClick={() => setActiveTab('messages')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all relative ${activeTab === 'messages' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconMail className="w-5 h-5" /><span className="font-medium">{t.messages}</span>{unreadMessagesCount > 0 && <span className="absolute rtl:left-4 ltr:right-4 bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{unreadMessagesCount}</span>}</button>
                <button onClick={() => setActiveTab('projects')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'projects' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconProject className="w-5 h-5" /><span className="font-medium">{t.projects}</span></button>
                <button onClick={() => setActiveTab('forms')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'forms' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconClipboard className="w-5 h-5" /><span className="font-medium">{t.forms}</span></button>
                <button onClick={() => setActiveTab('sales')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'sales' ? 'bg-green-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconMoney className="w-5 h-5" /><span className="font-medium">{t.sales}</span></button>
                {(isAdmin || isMaster) && (<button onClick={() => setActiveTab('financial')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'financial' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconChart className="w-5 h-5" /><span className="font-medium">{t.financial}</span></button>)}
                {hasCustomerAccess && (<button onClick={() => setActiveTab('customers')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'customers' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconUsers className="w-5 h-5" /><span className="font-medium">{t.customers}</span></button>)}
                {hasTariffAccess && (<button onClick={() => setActiveTab('services')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'services' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconBriefcase className="w-5 h-5" /><span className="font-medium">{t.services}</span></button>)}
                {isAdmin && (<><div className="px-4 py-2 text-xs font-bold text-gray-400 mt-4 border-t border-gray-100 pt-4">Admin</div><button onClick={() => setActiveTab('personnel')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconShield className="w-5 h-5" /><span className="font-medium">{t.personnel}</span></button><button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconSettings className="w-5 h-5" /><span className="font-medium">{t.settings}</span></button></>)}
                {isMaster && (<><button onClick={() => setActiveTab('logs')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'logs' ? 'bg-gray-800 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconHistory className="w-5 h-5" /><span className="font-medium">{t.logs}</span></button><button onClick={() => setActiveTab('reports')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconBarChart2 className="w-5 h-5" /><span className="font-medium">{t.reports}</span></button><button onClick={() => setActiveTab('kpi')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'kpi' ? 'bg-pink-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconTarget className="w-5 h-5" /><span className="font-medium">{t.kpi}</span></button></>)}
            </div>
            <button onClick={onLogout} className="w-full text-sm font-medium text-red-600 bg-red-50 hover:bg-red-100 py-3 rounded-xl transition-colors mt-6">{t.logout}</button>
        </div>
      </div>

      <div className="flex-grow">
        {activeTab === 'overview' && (
            <div className="space-y-8 animate-fade-in">
                 <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.myTasks}</div><div className="text-2xl font-black text-indigo-600">{myTasks.filter(t => t.status !== 'تکمیل شده' && t.status !== 'لغو شده').length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.allRequests}</div><div className="text-2xl font-black text-gray-800">{tickets.filter(t => t.status !== 'تکمیل شده').length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.activeProjects}</div><div className="text-2xl font-black text-purple-600">{tickets.filter(t => t.projectData?.isActive).length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.newMessages}</div><div className="text-2xl font-black text-blue-600">{unreadMessagesCount}</div></div>
                 </div>

                 {userKPIs.length > 0 && (
                     <div className="bg-pink-50 border border-pink-100 rounded-2xl p-6 shadow-sm">
                         <h3 className="font-bold text-pink-900 flex items-center gap-2 mb-4"><IconTarget className="w-5 h-5" /> {t.kpiWidget}</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                             {userKPIs.map(k => {
                                 const progress = Math.min(100, Math.round((k.currentValue / k.targetValue) * 100));
                                 return (
                                     <div key={k.id} className="bg-white p-4 rounded-xl border border-pink-100 shadow-sm">
                                         <div className="flex justify-between items-center mb-1">
                                             <span className="text-sm font-bold text-gray-800">{k.title}</span>
                                             <span className="text-xs bg-gray-100 text-gray-500 px-2 py-0.5 rounded">{k.period}</span>
                                         </div>
                                         <div className="text-xs text-gray-500 mb-2">{k.currentValue} / {k.targetValue} {k.unit}</div>
                                         <div className="w-full bg-gray-100 rounded-full h-1.5 overflow-hidden">
                                             <div className={`h-full rounded-full ${progress >= 100 ? 'bg-green-500' : progress >= 70 ? 'bg-blue-500' : 'bg-pink-500'}`} style={{ width: `${progress}%` }}></div>
                                         </div>
                                     </div>
                                 );
                             })}
                         </div>
                     </div>
                 )}

                 {myPendingTasks.length > 0 && (
                     <div className="bg-amber-50 border border-amber-200 rounded-2xl p-6 shadow-sm">
                         <div className="flex justify-between items-center mb-4"><h3 className="font-bold text-amber-900 flex items-center gap-2"><IconList className="w-5 h-5 text-amber-600" /> {t.pendingTasks} ({myPendingTasks.length})</h3><button onClick={() => setActiveTab('tasks')} className="text-amber-700 hover:text-amber-900 text-sm font-bold underline">{t.viewAll}</button></div>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">{myPendingTasks.slice(0, 4).map(task => (<div key={task.id} className="bg-white p-4 rounded-xl border border-amber-100 flex justify-between items-center shadow-sm hover:shadow-md transition-shadow"><div><div className="font-bold text-gray-800 text-sm mb-1">{task.title}</div><div className="text-xs text-gray-500 flex items-center gap-2"><span className={`px-2 py-0.5 rounded ${task.priority === 'High' ? 'bg-red-100 text-red-600' : 'bg-gray-100'}`}>{task.priority}</span><span>{task.creatorName}</span></div></div><button onClick={() => setActiveTab('tasks')} className="bg-amber-100 text-amber-800 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-amber-200">{t.doTask}</button></div>))}</div>
                     </div>
                 )}
                 <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
