                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">{activeProjects.map(project => (<div key={project.id} className="bg-white rounded-2xl border border-gray-200 p-5 shadow-sm hover:shadow-lg transition-all cursor-pointer group relative overflow-hidden" onClick={() => setSelectedTicketId(project.id)}><div className="absolute top-0 left-0 w-1 h-full bg-purple-500"></div><div className="flex justify-between items-start mb-3"><span className="text-xs font-bold text-gray-400">#{project.id}</span><span className={`text-[10px] px-2 py-0.5 rounded border ${getStatusBadge(project.status)}`}>{project.status}</span></div><h3 className="font-bold text-gray-900 mb-1">{project.customerName}</h3><p className="text-xs text-gray-500 mb-4">{getServiceTitle(project.serviceId)}</p><div className="mb-4"><div className="flex justify-between text-xs text-gray-500 mb-1"><span>{t.progress}</span><span className="font-bold text-purple-600">{project.projectData?.progress}%</span></div><div className="w-full bg-gray-100 rounded-full h-1.5"><div className="bg-purple-500 h-1.5 rounded-full transition-all" style={{ width: `${project.projectData?.progress}%` }}></div></div></div><div className="flex items-center justify-between text-xs text-gray-400"><span>{new Date(project.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span><span className="group-hover:text-purple-600 font-bold transition-colors">{t.view} →</span></div></div>))} {activeProjects.length === 0 && <div className="col-span-full py-12 text-center text-gray-400 bg-white rounded-2xl border border-dashed border-gray-200">{t.notFound}</div>}</div>
