                                <p className="text-xs text-gray-400 mt-1">فرم‌های جدید را می‌توانید از بخش تنظیمات ایجاد کنید.</p>
                            </div>
                        )}
                    </div>
                )}
            </div>
        )}

        {/* Sales Dashboard Tab */}
        {activeTab === 'sales' && (
            <SalesDashboard 
                currentUser={currentUser}
                personnel={personnel}
                services={services}
                onUpdatePersonnel={onUpdatePersonnel}
                onUpdateServices={onUpdateServices}
                lang={lang}
            />
        )}

        {activeTab === 'messages' && <InternalMessenger currentUser={currentUser} personnel={personnel} messages={messages} lang={lang} />}
        {activeTab === 'tasks' && <TaskManager currentUser={currentUser} personnel={personnel} tasks={tasks} lang={lang} />}
        {activeTab === 'meetings' && <MeetingCalendar meetings={meetings} currentUser={currentUser} personnel={personnel} lang={lang} />}
        {activeTab === 'customers' && hasCustomerAccess && <CustomerManager customers={customers} currentUser={currentUser} onUpdate={onUpdateCustomers} onEdit={onEditCustomer} onDelete={onDeleteCustomer} lang={lang} />}
        {activeTab === 'services' && hasTariffAccess && <ServiceManager services={services} onUpdate={onUpdateServices} readonly={!isAdmin && !isMaster} lang={lang} />}
        {activeTab === 'personnel' && isAdmin && <PersonnelManager personnel={personnel} config={config} onUpdate={onUpdatePersonnel} onUpdateConfig={onUpdateConfig} lang={lang} />}
        {activeTab === 'settings' && isAdmin && <SettingsManager config={config} onUpdate={onUpdateConfig} isMaster={isMaster} />}
        {activeTab === 'reports' && isMaster && <PerformanceReports personnel={personnel} tickets={tickets} tasks={tasks} lang={lang} />}
        {activeTab === 'kpi' && isMaster && <KPIManager kpis={kpis} personnel={personnel} lang={lang} />}
        {activeTab === 'logs' && isMaster && (
            <div className="space-y-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm"><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><IconHistory className="w-6 h-6" /> {t.auditLogs}</h2></div>
                <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden"><table className="w-full text-start text-sm"><thead className="bg-gray-50 text-gray-500"><tr><th className="px-4 py-3">{t.time}</th><th className="px-4 py-3">{t.user}</th><th className="px-4 py-3">{t.operation}</th><th className="px-4 py-3">{t.entity}</th><th className="px-4 py-3">{t.details}</th><th className="px-4 py-3">{t.action}</th></tr></thead><tbody className="divide-y divide-gray-100">{systemLogs.map(log => (<tr key={log.id} className="hover:bg-gray-50"><td className="px-4 py-3 text-gray-500 dir-ltr text-right">{new Date(log.timestamp).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</td><td className="px-4 py-3 font-bold text-gray-700">{log.actorName}</td><td className="px-4 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${log.actionType === 'DELETE' ? 'bg-red-100 text-red-700' : (log.actionType === 'CREATE' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700')}`}>{log.actionType}</span></td><td className="px-4 py-3">{log.entity}</td><td className="px-4 py-3 text-gray-600 truncate max-w-xs" title={log.details}>{log.details}</td><td className="px-4 py-3">{log.actionType === 'DELETE' && log.backupData && (<button onClick={() => handleRestore(log)} className="text-blue-600 hover:bg-blue-50 px-2 py-1 rounded flex items-center gap-1 font-bold text-xs"><IconRefreshCw className="w-3 h-3" /> {t.restore}</button>)}</td></tr>))}</tbody></table>{systemLogs.length === 0 && <div className="p-8 text-center text-gray-400">{t.noLogs}</div>}</div>
            </div>
        )}
        {activeTab === 'financial' && (isAdmin || isMaster) && renderFinancialReport()}
      </div>

      {selectedTicket && renderTicketModal()}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Personnel, SalesRecord, ServiceOption, Currency } from '../types';
import { IconMoney, IconPlus, IconChart, IconUsers, IconTrophy, IconPercent, IconEdit, IconCheck, IconSearch } from './Icons';
import { saveSalesRecord, subscribeToSalesRecords, updateSalesRecord, savePersonnelToCloud, saveServicesToCloud } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  services: ServiceOption[];
  onUpdatePersonnel: (personnel: Personnel[]) => void;
  onUpdateServices: (services: ServiceOption[]) => void;
  lang: Language;
}

export const SalesDashboard: React.FC<Props> = ({ currentUser, personnel, services, onUpdatePersonnel, onUpdateServices, lang }) => {
  const [activeTab, setActiveTab] = useState<'new_sale' | 'my_sales' | 'all_sales' | 'commissions' | 'leaderboard'>('my_sales');
  const [salesRecords, setSalesRecords] = useState<SalesRecord[]>([]);
  const isMaster = currentUser.username === 'master';

  // New Sale Form State
  const [newSale, setNewSale] = useState({
      serviceId: '',
      salespersonId: currentUser.id,
      customerName: '',
      amount: '',
      currency: 'IRR' as Currency,
      depositAccount: '',
      depositDate: new Date().toISOString().split('T')[0],
      notes: ''
  });

  // Commission Settings State (Master Only)
  const [selectedUserForCommission, setSelectedUserForCommission] = useState<string>('');

  // Edit Sales State (Master Only)
  const [editingSale, setEditingSale] = useState<SalesRecord | null>(null);

  const t = {
      fa: {
          header: 'مدیریت فروش و کمیسیون',
          sub: 'ثبت تراکنش‌ها، محاسبه کمیسیون و گزارش‌گیری',
          tabs: {
              new: 'ثبت فروش جدید',
              my: 'فروش‌های من',
              all: 'کل فروش‌ها',
              settings: 'تنظیمات کمیسیون',
              top: 'برترین‌ها'
          },
          form: {
              salesperson: 'فروشنده',
              service: 'خدمت فروخته شده',
              customer: 'نام مشتری',
              amount: 'مبلغ واریزی',
              currency: 'ارز',
              account: 'حساب مقصد',
              date: 'تاریخ واریز',
              notes: 'توضیحات (اختیاری)',
              submit: 'ثبت نهایی فروش',
              calcCommission: 'کمیسیون تخمینی:',
              success: 'فروش با موفقیت ثبت شد.'
          },
          table: {
              seller: 'فروشنده',
              service: 'سرویس',
              customer: 'مشتری',
              amount: 'مبلغ',
              commission: 'سهم فروشنده',
              date: 'تاریخ',
              actions: 'عملیات',
              edit: 'ویرایش',
              save: 'ذخیره',
              cancel: 'لغو'
          },
          settings: {
              selectUser: 'انتخاب فروشنده جهت تنظیم درصد',
              baseRate: 'درصد پایه سرویس',
              userRate: 'درصد اختصاصی کاربر',
              update: 'بروزرسانی درصدها'
          },
          stats: {
              totalSales: 'فروش کل',
              totalCommission: 'دریافتی کل',
              count: 'تعداد'
          }
      },
      en: {
          header: 'Sales & Commission Management',
          sub: 'Record transactions, calculate commissions, and reporting',
          tabs: {
              new: 'New Sale',
              my: 'My Sales',
              all: 'All Sales',
              settings: 'Commission Settings',
              top: 'Leaderboard'
          },
          form: {
              salesperson: 'Salesperson',
              service: 'Sold Service',
              customer: 'Customer Name',
              amount: 'Amount',
              currency: 'Currency',
              account: 'Deposit Account',
              date: 'Deposit Date',
              notes: 'Notes (Optional)',
              submit: 'Submit Sale',
              calcCommission: 'Est. Commission:',
              success: 'Sale recorded successfully.'
          },
          table: {
              seller: 'Seller',
              service: 'Service',
              customer: 'Customer',
              amount: 'Amount',
              commission: 'Commission',
              date: 'Date',
              actions: 'Actions',
              edit: 'Edit',
              save: 'Save',
              cancel: 'Cancel'
          },
          settings: {
              selectUser: 'Select Salesperson',
              baseRate: 'Service Base Rate',
              userRate: 'User Custom Rate',
              update: 'Update Rates'
          },
          stats: {
              totalSales: 'Total Sales',
              totalCommission: 'Total Commission',
              count: 'Count'
          }
      }
  }[lang];

  useEffect(() => {
      const unsub = subscribeToSalesRecords(setSalesRecords);
      return () => unsub();
  }, []);

  // Filter sales personnel
  const salesPersonnel = personnel.filter(p => 
      p.roles.some(r => r.includes('فروش') || r.toLowerCase().includes('sales')) || p.username === 'master'
  );

  const getCommissionRate = (userId: string, serviceIdOrSubId: string): number => {
      // Find the service (it might be a main service OR a sub-service ID)
      let service = services.find(s => s.id === serviceIdOrSubId);

      // If not found, check if it is a sub-service and find its parent
      if (!service) {
          service = services.find(s => s.subServices?.some(sub => sub.id === serviceIdOrSubId));
      }

      const user = personnel.find(p => p.id === userId);

      if (!service) return 0;

      // 1. Check User Specific Override (Keyed by PARENT service ID)
      if (user?.customCommissions && user.customCommissions[service.id] !== undefined) {
          return user.customCommissions[service.id];
      }

      // 2. Check Service Default
      if (service.defaultCommission !== undefined) {
          return service.defaultCommission;
      }

      // 3. Fallback
      return 0;
  };

  const handleSaleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newSale.amount || !newSale.serviceId || !newSale.customerName) return;

      const amount = parseFloat(newSale.amount.replace(/,/g, ''));
      const rate = getCommissionRate(newSale.salespersonId, newSale.serviceId);
      const commission = (amount * rate) / 100;

      const salesperson = personnel.find(p => p.id === newSale.salespersonId);

      // Resolve Service Title (Main or Sub)
      let serviceTitle = 'Unknown';
      const mainService = services.find(s => s.id === newSale.serviceId);

      if (mainService) {
          serviceTitle = mainService.title;
      } else {
          // Look for sub-service
          for (const s of services) {
              const sub = s.subServices?.find(sub => sub.id === newSale.serviceId);
              if (sub) {
                  serviceTitle = `${s.title} - ${sub.title}`;
                  break;
              }
          }
      }

      const record: SalesRecord = {
          id: `sale-${Date.now()}`,
          salespersonId: newSale.salespersonId,
          salespersonName: salesperson?.fullName || 'Unknown',
          serviceId: newSale.serviceId,
          serviceTitle: serviceTitle,
          customerName: newSale.customerName,
          saleAmount: amount,
          currency: newSale.currency,
          commissionRate: rate,
          commissionAmount: commission,
          depositAccount: newSale.depositAccount,
          depositDate: newSale.depositDate,
          notes: newSale.notes,
          createdAt: new Date().toISOString()
      };

      await saveSalesRecord(record);
      alert(t.form.success);
      setNewSale({ ...newSale, amount: '', customerName: '', notes: '' });
      setActiveTab('my_sales');
  };

  const handleUpdateCommission = (serviceId: string, newRate: number) => {
      if (!selectedUserForCommission) return; // Updating Global Service Default

      const updatedPersonnel = personnel.map(p => {
          if (p.id === selectedUserForCommission) {
              return {
                  ...p,
                  customCommissions: {
                      ...p.customCommissions,
                      [serviceId]: newRate
                  }
              };
          }
          return p;
      });
      onUpdatePersonnel(updatedPersonnel);
  };

  const handleUpdateServiceDefault = (serviceId: string, newRate: number) => {
      const updatedServices = services.map(s => 
          s.id === serviceId ? { ...s, defaultCommission: newRate } : s
      );
      onUpdateServices(updatedServices);
  };

  const handleEditSale = async () => {
      if (!editingSale) return;
      await updateSalesRecord(editingSale.id, editingSale, currentUser.fullName);
      setEditingSale(null);
  };

  const formatNumber = (num: number) => num.toLocaleString();

  // Stats Calculation
  const calculateStats = (records: SalesRecord[]) => {
      return {
          totalSales: records.reduce((acc, r) => acc + r.saleAmount, 0),
          totalCommission: records.reduce((acc, r) => acc + r.commissionAmount, 0),
          count: records.length
      };
  };

  const mySales = salesRecords.filter(r => r.salespersonId === currentUser.id);
  const displaySales = activeTab === 'all_sales' && isMaster ? salesRecords : mySales;
  const stats = calculateStats(displaySales);

