              calcCommission: 'کمیسیون تخمینی:',
              success: 'فروش با موفقیت ثبت شد.'
          },
          table: {
              seller: 'فروشنده',
              service: 'سرویس',
              customer: 'مشتری',
              amount: 'مبلغ',
              commission: 'سهم فروشنده',
              date: 'تاریخ',
              actions: 'عملیات',
