  const handleAssignTicket = async () => {
      if (!selectedTicket) return;

      let finalAssignedId = '';
      const activePersonnel = personnel.filter(p => p.status === 'active');

      if (assignmentType === 'manual') {
          if (!tempAssignedTo) return;
          finalAssignedId = tempAssignedTo;
      } 
      else if (assignmentType === 'random') {
          // Exclude 'Manager' role if desired, or just pick any active staff
          // Here assuming general staff assignment
          const candidates = activePersonnel.filter(p => !p.roles.includes('مدیر'));
          if (candidates.length === 0) {
              alert(t.noEligible);
              return;
          }
          const randomIndex = Math.floor(Math.random() * candidates.length);
          finalAssignedId = candidates[randomIndex].id;
      }
      else if (assignmentType === 'role') {
          if (!assignmentRole) return;
          const candidates = activePersonnel.filter(p => p.roles.includes(assignmentRole));
          if (candidates.length === 0) {
              alert(t.noEligible);
              return;
          }
          // Randomly pick one from the specific role (Load Balancing simple approximation)
          const randomIndex = Math.floor(Math.random() * candidates.length);
          finalAssignedId = candidates[randomIndex].id;
      }

      if (!finalAssignedId) return;

      if (finalAssignedId === selectedTicket.assignedTo) return;

      const targetUser = personnel.find(p => p.id === finalAssignedId);
      const actionDesc = targetUser 
          ? `Assigned to ${targetUser.fullName} (${assignmentType === 'manual' ? 'Manual' : 'Auto'})` 
          : 'Unassigned';

      onUpdateTicket(selectedTicket.id, { assignedTo: finalAssignedId }, currentUser.fullName, actionDesc);
      logSystemAction('UPDATE', 'Ticket', `Assigned ticket ${selectedTicket.id} to ${finalAssignedId}`, currentUser.fullName, selectedTicket.id);

      if (targetUser && targetUser.id !== currentUser.id) {
          const msg: InternalMessage = {
              id: `notify-${Date.now()}`,
              senderId: currentUser.id,
              senderName: 'System',
              recipientIds: [targetUser.id],
              recipientNames: [targetUser.fullName],
              subject: `Assignment: ${selectedTicket.customerName}`,
              body: `Ticket #${selectedTicket.id} has been assigned to you.`,
              createdAt: new Date().toISOString(),
              readBy: []
          };
          await sendInternalMessage(msg);
      }
      alert(t.assignSuccess);
  };
